 4	public final class BellmanFord {
 5	    private static final int INF = 100_000_000;
 6	    private static final int[] NEGATIVE_CYCLE_RESULT = {-1};
 7	
 8	    private BellmanFord() {
 9	    }
10	
11	    public static int[] bellmanFord(int vertices, int[][] edgeData, int source) {
12	        return shortestPaths(vertices, edgeData, source);
13	    }
14	
15	    public static int[] shortestPaths(int vertices, int[][] edgeData, int source) {
16	        ShortestPathResult result = computeShortestPaths(WeightedGraph.from(vertices, edgeData), source);
17	        if (result.hasNegativeCycle()) {
18	            return NEGATIVE_CYCLE_RESULT.clone();
19	        }
20	        return result.distances();
21	    }
22	
23	    public static ShortestPathResult computeShortestPaths(WeightedGraph graph, int source) {
24	        validateSource(source, graph.vertices());
25	        List<WeightedEdge> edges = graph.edges();
26	        int[] distances = initializeDistances(graph.vertices(), source);
27	
28	        for (int pass = 0; pass < graph.vertices() - 1; pass++) {
29	            boolean updated = false;
30	
31	            for (WeightedEdge edge : edges) {
32	                updated |= relax(edge, distances);
33	            }
34	
35	            if (!updated) {
36	                return ShortestPathResult.success(distances);
37	            }
38	        }
39	
40	        if (hasNegativeCycle(edges, distances)) {
41	            return ShortestPathResult.negativeCycle();
42	        }
43	
44	        return ShortestPathResult.success(distances);
45	    }
46	
47	    private static int[] initializeDistances(int vertices, int source) {
48	        int[] distances = new int[vertices];
49	        Arrays.fill(distances, INF);
50	        distances[source] = 0;
51	        return distances;
52	    }
53	
54	    private static boolean relax(WeightedEdge edge, int[] distances) {
55	        if (distances[edge.from()] == INF) {
56	            return false;
57	        }
58	
59	        int candidateDistance = distances[edge.from()] + edge.weight();
60	        if (candidateDistance >= distances[edge.to()]) {
61	            return false;
62	        }
63	
64	        distances[edge.to()] = candidateDistance;
65	        return true;
66	    }
67	
68	    private static boolean hasNegativeCycle(List<WeightedEdge> edges, int[] distances) {
69	        for (WeightedEdge edge : edges) {
70	            if (distances[edge.from()] != INF
71	                    && distances[edge.from()] + edge.weight() < distances[edge.to()]) {
72	                return true;
73	            }
74	        }
75	        return false;
76	    }
77	
78	    private static void validateSource(int source, int vertices) {
79	        validateVertex(source, vertices, "source");
80	    }
81	
82	    private static void validateVertex(int vertex, int vertices, String label) {
83	        if (vertex < 0 || vertex >= vertices) {
84	            throw new IllegalArgumentException(label + " must be within the vertex range");
85	        }
86	    }
87	}

